import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
/**
 * A button that displays a check mark when active, used for the group filters.
 */
export default class CheckableButton extends Button {
  getButtonContent(children) {
    const content = super.getButtonContent(children);
    if (this.attrs.checked) {
      content.push(m(Icon, {
        name: "fas fa-check",
        className: "Button-icon ButtonCheck"
      }));
    }
    return content;
  }
}
flarum.reg.add('framio-community', 'user-directory/forum/components/CheckableButton', CheckableButton);