import app from 'flarum/forum/app';
import AbstractType from './AbstractType';
/**
 * Matches free text, i.e. anything that is not a recognised gambit.
 */
export default class TextFilter extends AbstractType {
  resourceType() {
    return 'fof-user-directory-text';
  }
  search(query) {
    if (!query) {
      this.suggestions = [];
      return;
    }
    this.suggestions = [this.createRecord(query)];
  }
  renderKind() {
    return app.translator.trans('fof-user-directory.forum.search.kinds.text');
  }
  renderLabel(resource) {
    return m("div", {
      className: "UserDirectorySearchLabel"
    }, resource.text());
  }
  applyFilter(params, resource) {
    params.q = params.q ? `${params.q} ` : '';
    params.q += resource.text();
  }
  initializeFromParams(params) {
    if (!params.q) {
      return Promise.resolve([]);
    }
    return Promise.resolve(params.q.split(' ')
    // Words containing a colon are gambits, which other filters handle.
    .filter(word => word !== '' && !word.includes(':')).map(word => this.createRecord(word)));
  }
  createRecord(text) {
    return app.store.createRecord('fof-user-directory-text', {
      attributes: {
        text
      }
    });
  }
}
flarum.reg.add('framio-community', 'user-directory/forum/searchTypes/TextFilter', TextFilter);