import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import ItemList from 'flarum/common/utils/ItemList';
import subscriptionOptions from '../utils/subscriptionOptions';
import SubscriptionOptionItem from './SubscriptionOptionItem';
import Stream from 'flarum/common/utils/Stream';
export default class SubscriptionModal extends Modal {
  canShowTooltip = (() => undefined)();
  oninit(vnode) {
    super.oninit(vnode);
    this.loading = Stream(false);
    this.subscription = this.attrs.model.subscription() || 'not_follow';
    const preferences = app.session.user?.preferences();
    const notifyEmail = preferences?.['notify_newPostInTag_email'];
    const notifyAlert = preferences?.['notify_newPostInTag_alert'];
    if ((notifyEmail || notifyAlert) && this.subscription === 'not_follow') {
      this.canShowTooltip = true;
    } else {
      this.canShowTooltip = false;
    }
  }
  className() {
    return 'SubscriptionModal Modal--medium';
  }
  title() {
    return app.translator.trans('fof-follow-tags.forum.sub_controls.header', {
      tagName: this.attrs.model.name()
    });
  }
  content() {
    const preferences = app.session.user?.preferences();
    const notifyEmail = preferences?.['notify_newPostInTag_email'];
    const notifyAlert = preferences?.['notify_newPostInTag_alert'];
    return m("div", {
      className: "Modal-body"
    }, this.formOptionItems().toArray(), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary",
      onclick: () => this.saveSubscription(this.subscription),
      loading: this.loading()
    }, app.translator.trans('fof-follow-tags.forum.sub_controls.submit_button'))));
  }
  formOptionItems() {
    const items = new ItemList();
    items.add('subscription_type', m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('fof-follow-tags.forum.sub_controls.subscription_label', {
      tagName: this.attrs.model.name()
    })), this.subscriptionOptionItems().toArray()), 60);
    return items;
  }
  subscriptionOptionItems() {
    const items = new ItemList();
    let priority = 100;
    subscriptionOptions.forEach((option, index) => {
      const attrs = {
        ...option,
        onclick: () => {
          this.subscription = option.subscription;
          this.canShowTooltip = false;
        },
        active: this.subscription === option.subscription,
        disabled: option.subscription === 'hide' && this.attrs.model.isHidden()
      };
      items.add(`subscription-option-${index}`, m(SubscriptionOptionItem, attrs), priority);
      priority -= 5;
    });
    return items;
  }
  saveSubscription(subscription) {
    const tag = this.attrs.model;
    this.loading(true);
    this.subscription = subscription;

    // Use standard JSON:API PATCH to update the tag resource
    tag.save({
      subscription: this.subscription
    }).then(() => {
      this.loading(false);
      m.redraw();
      this.hide();
    }).catch(() => {
      this.loading(false);
      m.redraw();
    });
  }
}
flarum.reg.add('framio-community', 'follow-tags/forum/components/SubscriptionModal', SubscriptionModal);